import type { ProfileReference } from '../../types/design-profile';

const MAX_OBSERVATION_CHARACTERS = 8_000;
const UNTITLED_REFERENCE = 'Saved reference';

export const provisionalDescription = (
  reference: Pick<ProfileReference, 'title' | 'text'>,
): string =>
  [...new Set([reference.title.trim(), reference.text.trim()])]
    .filter(Boolean)
    .join('\n')
    .slice(0, MAX_OBSERVATION_CHARACTERS)
    .trim() || UNTITLED_REFERENCE;
